  "—／未知": "— / Unknown",
  "“为目标每月需存”是以你选的退休时间来算，要每月存多少；“你估计每月能存”是你自己的估计。上面的结论用你的估计来判断，也会考虑能否按时付款，不能只比较两个金额。": "“Monthly savings needed for goal” is how much you need to save each month based on the retirement date you chose; “Your estimated monthly savings” is your own estimate. The conclusion above is based on your estimate and also considers whether you can make payments on time; it isn't just a comparison of the two amounts.",
  "“预计不靠工资”标记表示按你设的投入、收入和支出，资金第一次能用到规划终点的月份。“所需”已考虑之后计划存入的钱，表示各时点至少要有多少余额；“预计”表示按当前条件算出的资金变化。": "The “projected without salary” marker shows the first month your funds last through the end of planning, based on the contributions, income, and expenses you set. “Required” already includes money you plan to add later and shows the minimum balance needed at each point; “Projected” shows how funds change under current conditions.",
