  "一笔支出": "One expense",
  "一笔本人账户转账只存一条记录；金额、端点或用途无法确定时不要保存成虚构事实。记录资金流动不会改变账户余额，也不会自动生成收入或支出。": "A transfer between your own accounts is saved as a single entry; if the amount, from/to accounts, or purpose can’t be determined, don’t save it as fact. Recording cash flow doesn’t change account balances or automatically create income or expenses.",
