  "下移": "Move Down",
  "下跌分别放在退休开头和末段，持续时间相同、最多一年；其余时间沿用所设收益。基准不含下跌，两条压力路径只改变顺序。": "Downturns are placed at the start and end of retirement respectively, each lasting the same duration of up to one year; the rest of the time uses the set returns. The baseline excludes downturns; the two stress paths only change the order.",
