  "下面的答案会按“你现在每月攒的钱”的 0%、25%、50%、75% 各算一遍，所以这里不用再填每月能攒多少。": "The answers below are calculated at 0%, 25%, 50%, and 75% of what you save each month now, so you don't need to enter your monthly savings here.",
