  "不限": "No Limit",
  "不预测失业风险、复工时间或工资变化；每月付款先后只在不工作区间检查。未来收入和受限资金是否计入，以上述本次假设为准。公积金周期缴存、提取与余额耗尽尚未推演。": "Does not predict job-loss risk, return-to-work timing, or salary changes; the order of monthly payments is checked only during the not-working period. Whether future income and restricted funds are included follows the assumptions above. Recurring housing provident fund contributions, withdrawals, and balance depletion are not yet projected.",
