  "之后每期自动续费，不确定何时结束就不用填到期日。": "It renews automatically each period afterward. If you're unsure when it ends, you don't need to enter an end date.",
  "也可以在盘点时直接把账户标为已注销。已有盘点记录的账户保留历史，只能停用，不能删除。": "You can also mark an account as closed during a check-in. Accounts with check-in history keep their history; they can only be deactivated, not deleted.",
