  "买房、买车、装修、婚礼、养孩子与更多 · 影响目标结果": "Buying a home, a car, renovations, a wedding, raising kids, and more · affects goal results",
  "买房、买车、装修这类大额支出，可以先设想一笔，看看对停工时间的影响。模板里的金额只是占位，请改成自己的估计。": "For major expenses like buying a home, buying a car, or renovating, you can add a hypothetical expense to see how it affects when you can stop working. The amounts in the template are only placeholders; replace them with your own estimates.",
  "买房买车等大额计划": "Major plans like buying a home or car",
