  "于 {v1}": "on {v1}",
  "云盘或外接盘上只会得到未加密的备份文件。已有的加密备份不会被删除或改写，仍需要对应的恢复密钥才能打开。": "Cloud or external drives will only receive unencrypted backup files. Existing encrypted backups won't be deleted or overwritten and still require the matching recovery key to open.",
  "云盘或外接盘上只会得到未加密的备份文件。已有的加密备份不会被删除或改写，仍需要对应的恢复密钥才能打开。自动备份开关保持现状。": "Cloud or external drives will only receive unencrypted backup files. Existing encrypted backups won't be deleted or overwritten and still require the matching recovery key to open. The automatic backup toggle stays as it is.",
  "五": "Five",
  "交通": "Transport",
