  "人民币": "Chinese yuan",
  "人民币或未知金额不能填写原币和汇率。": "CNY or unknown amounts can't have an original currency or exchange rate.",
  "人民币账户不能填写原币金额": "CNY accounts can't have an original currency amount",
  "什么可能破坏此计划？": "What could derail this plan?",
  "什么时候退休": "When will you retire?",
  "仅供参考：{reference}资产增减混有估值涨跌，不等于日常收支留下的钱，不会自动填入。": "For reference only: changes in {reference} assets include valuation gains and losses, so they don't equal the money left over from day-to-day income and expenses, and won't be filled in automatically.",
  "仅充值、还没扣款时先关闭。误记已付可改为「本期不付」或删除这条记录；真实退款请保留原付款依据。": "If you only topped up and haven't been charged yet, turn it off first. If it was marked paid by mistake, change it to \"Skip this period\" or delete the entry; for an actual refund, keep the original payment record.",
  "仅列有记录的年份 · 柱高为已知支出": "Only years with records are shown · bar height shows known spending",
  "仅向付款账户充值时，等服务实际扣款后再记录。取消续费保留以前的付款。": "If you only top up the payment account, record it after the service is actually charged. Canceling renewal keeps previous payments.",
  "仅安排已有账户资金的释放，不推算税费或未来缴存，不创建实际到账记录。不确定金额可以留空。": "Only schedules the release of funds already in existing accounts; it doesn't estimate taxes or future contributions or create actual receipt records. Leave blank if you're unsure of the amount.",
  "仅实物": "Physical only",
  "仅对所列条件有效；工作阶段月内付款未完整检查。无需正投入不等于可以额外提款。": "Valid only for the listed conditions; payments in working-phase months weren't fully checked. Not needing a positive contribution doesn't mean extra withdrawals are allowed.",
  "仅已知部分": "Known portion only",
  "仅已知部分 {v1}": "Known portion only {v1}",
  "仅已知部分 · {unknown_count} 笔金额待补": "Known portion only · Entries with amounts to be added: {unknown_count}",
  "仅已知部分；{unknown} 笔金额待补": "Only known amounts; entries to be added: {unknown}",
  "仅已记录支出；退款按发生日期，售出回收单列。物品的购入与维护从物品里读取。": "Recorded expenses only; refunds by date incurred, sale proceeds listed separately. Item purchase and maintenance costs come from item records.",
  "仅已记录支出；退款按发生日期；售出回收单列；搜索只筛选明细。": "Recorded expenses only; refunds by date incurred; sale proceeds listed separately; search filters details only.",
  "仅已记录税后到账；记录数量不证明区间覆盖完整，公积金缴存单列": "Recorded after-tax income only; the number of records does not prove full period coverage, and housing fund contributions are listed separately",
