  "从当前方案、某份基准或两份比较生成报告后，在此预览。": "After generating a report from the current plan, a baseline, or a comparison of two plans, preview it here.",
  "从截至日后按完整月检查，月初先付开销、月底再到账。不计收益、通胀、未来大额计划或月供结束。必要开销需自行包含房租、月供、社保等全部支出。资金不足以付整月不等于余额耗尽。": "Checks whole months after the cutoff date: expenses are paid at the start of the month and income arrives at the end. Does not account for investment returns, inflation, future major plans, or loan payments ending. You must include all essential expenses, such as rent, loan payments, and social insurance. Having insufficient funds for a whole month does not mean the balance is depleted.",
  "从截至日后按完整月检查：月初先付开销，月底再到账。底线检查付款后的最低余额。资金不足以付整月不等于余额已耗尽。": "Checks whole months after the cutoff date: expenses are paid at the start of the month and income arrives at the end. The floor check looks at the lowest balance after payments. Not having enough funds to cover a whole month does not mean the balance is depleted.",
