  "例如「买房」「换车」「装修」": "e.g. buy a house, replace the car, renovate",
  "例如每月到账 10000 元、全部开销 6000 元，就填 4000 元。包括买基金等留下的钱，不包含投资涨跌。没想好可以不填，以后再修改。": "For example, if you receive 10000 CNY each month and total expenses are 6000 CNY, enter 4000 CNY. Include money left after buying funds and similar, but not investment gains or losses. If you have not decided, leave it blank and edit it later.",
  "例如相机、镜头": "e.g. camera, lens",
  "例如退休后还要供孩子上学、赡养父母或护理费用。只计退休后的月份，额外叠加在生活费上，所以生活费总额里不要再包含。": "For example, paying for a child's education, supporting parents, or care costs after retirement. Count only the months after retirement and add these on top of living costs, so do not include them in total living costs again.",
  "例如退休后还要供孩子上学、赡养父母或护理费用。这些按“额外”计入，生活费总额里不要再包含；只计算退休后的月份，使用明确月份。": "For example, paying for a child's education, supporting parents, or care costs after retirement. These are counted as “extra,” so do not include them in total living costs again; count only post-retirement months and specify them explicitly.",
  "例如：Notion、域名、咖啡储值卡": "e.g. Notion, domain, prepaid coffee card",
  "例如：东京旅行": "e.g. Tokyo trip",
  "例如：中山路房租": "e.g. Zhongshan Road rent",
  "例如：京东": "e.g. JD.com",
  "例如：充值付款账户": "e.g. top-up payment account",
  "例如：存放在书房左侧柜；保修卡在抽屉": "e.g. stored in the left cabinet in the study; warranty card in the drawer",
  "例如：家电": "e.g. home appliances",
  "例如：转入银行、工资来源": "e.g. receiving bank, salary source",
  "例：投资账户赚 5000、转出 8000，余额减少 3000——损益 +5000，提款不等于消费；直接从投资账户支付生活费属于投资范围流出。范围外账户另付的投资费用不自动计入所选组合净损益，结果未包含该成本。": "Example: an investment account earns 5000 and you transfer out 8000, so the balance falls by 3000—profit/loss is +5000; a withdrawal is not spending. Paying living expenses directly from an investment account counts as an outflow within the investment scope. Investment fees paid separately from out-of-scope accounts are not automatically included in the selected portfolio's net gain/loss, so the result does not include that cost.",
