  "先在时间安排里确认年龄参考，或直接填写开始年月。": "First confirm the age reference in Timeline, or enter the start year and month directly.",
  "先在服务方取消自动扣费，再在这里确认最后使用日：到这一天为止仍在服务期，次日显示已结束。历史付款与估算依据保留，不再安排后续续费。这只维护记录，不代表已取消平台扣款。": "Cancel auto-renewal with the provider first, then confirm the last day of use here: the service remains active through that day and shows as ended the next day. Payment history and the estimate basis are retained, and no further renewals are scheduled. This only maintains the record; it does not mean the platform charge has been canceled.",
