  "全部不计入": "Exclude All",
  "全部为虚构资料与内存驱动：提交只改内存，不保存、不重新计算损益；真实端口接入前不代表原生行为。刷新重置。": "All data is fictional and memory-driven: submitting only changes memory and does not save or recalculate profit and loss. Until the real endpoint is connected, this does not represent native behavior. Refresh resets it.",
  "全部为虚构资料，结果来自固定夹具；提交只展示草稿，不保存、不重算损益。": "All data is fictional, and results come from a fixed fixture. Submitting only displays a draft; no data is saved, and profit and loss are not recalculated.",
  "全部付款 {payments_total} 笔（含已删 {payments_deleted} 笔）；价格 {rate_segments} 段、规则 {rule_segments} 段、特殊到期 {period_ends} 项、提醒 {reminders} 条。": "All payments: {payments_total} (including {payments_deleted} deleted); price segments: {rate_segments}, rule segments: {rule_segments}, special end dates: {period_ends}, reminders: {reminders}.",
