  "全部成功才写入；确定失败时资料不变，结果未知时只核对上次导入是否成功，不重复写入。": "Write only if all succeed. If it definitely fails, data stays unchanged; if the result is unknown, only check whether the last import succeeded and do not write again.",
  "全部是假设，不是事实。收益按扣除通胀后的实际收益填写。": "These are all assumptions, not facts. Enter returns as real returns after inflation.",
