  "公积金": "Housing Provident Fund",
  "公积金 {v1}": "Housing Provident Fund {v1}",
  "公积金未知": "Housing provident fund unknown",
  "公积金缴存": "Housing Provident Fund Contributions",
  "公积金缴存不能填入可靠到账；定期提取仅在余额足够且能持续整个检查期间时计入，已包含在起点的余额不能再次当作收入。留空表示未知，没有到账请明确打开。必要开销应包含当前房租、月供、社保等；这些费用不从退休预算或大额计划自动添加，避免重复。": "Housing provident fund contributions cannot be entered as reliable receipts. Periodic withdrawals count only if the balance is sufficient and can last the entire review period; balances already included at the starting point cannot be counted as income again. Leave blank if unknown; if nothing is received, turn this on explicitly. Essential expenses should include current rent, mortgage payments, social security, and similar costs; these are not added automatically from the retirement budget or major plans, to avoid duplication.",
  "公积金缴存不能当作到账；余额已包含在起点时，不要再次计作收入。定期提取须能持续整个检查期间。": "Housing provident fund contributions cannot be treated as received funds. If the balance is already included at the starting point, do not count it as income again. Periodic withdrawals must be able to last the entire review period.",
  "公积金缴存已知小计：{v1}；{hpf_unknown_count} 条金额未知。": "Known subtotal for housing provident fund contributions: {v1}; entries with unknown amounts: {hpf_unknown_count}.",
  "公积金缴存：{v1}；{hpf_unknown_count} 条金额未知。": "Housing provident fund contribution: {v1}; entries with unknown amounts: {hpf_unknown_count}.",
  "公积金默认金额未读取，已留空；请按实际金额填写，留空表示未知。": "The default housing provident fund amount couldn't be read and was left blank. Enter the actual amount, or leave it blank if unknown.",
  "公钥不可用，无法加密备份": "Public key unavailable; cannot encrypt backup",
  "公钥不可用，请检查安全配置": "Public key unavailable. Check your security settings.",
  "公钥标识 {v1}（界面只显示前 8 位）": "Public key ID {v1} (only the first 8 characters are shown)",
  "公钥标识 {v1}（界面只显示前 8 位，核对始终使用完整摘要）。": "Public key ID {v1} (only the first 8 characters are shown; verification always uses the full digest).",
