  "关于与帮助": "About & Help",
  "关于这件物品": "About This Item",
  "关掉不用的模块，会隐藏相关入口，已有资料保留。心愿、订阅续期和盘点提醒随对应模块暂停；保障提醒不受影响，重新开启后按原设置安排。": "Turning off modules you don't use hides their entries; existing data is kept. Wish, subscription renewal, and check-in reminders pause with their modules. Protection reminders are unaffected and resume with your original settings when you turn the module back on.",
  "关掉不用的模块，标签栏、总览和时间轴会隐藏它；资料不会删除，重新打开即恢复。": "Turning off modules you don't use hides them from the tab bar, Overview, and timeline. Data isn't deleted and returns when you turn them back on.",
  "关掉只保留这个设想，不影响退休结论": "Turning this off keeps this scenario only and doesn't affect retirement conclusions",
  "关掉后保留记录，本次计算不采用": "Turning this off keeps the record but excludes it from this calculation",
  "关掉表示可以压缩的灵活支出": "Turning this off marks it as flexible spending that can be cut",
  "关系修复影响已变化，请重新读取预览后再确认": "The repair impact has changed. Reload the preview before confirming.",
  "关联": "Link",
  "关联 {references} 条记录（含最近删除）。只删除选项，不删除物品或售出记录。": "Linked records: {references} (including Recently Deleted). Only the option is deleted; items and sale records are not.",
  "关联「{v1}」；付款记录由该计划管理": "Linked to \"{v1}\"; payment records are managed by this plan.",
  "关联一条已有的收入或重要支出记录（选填）：只说明同一笔现实发生，首版要求整笔、同额、同日，不产生额外余额或收益。没有可靠来源也可以不关联。": "Link an existing income or major expense record (optional): this only indicates the same real-world transaction. The first version requires the full amount, same amount, and same date, and creates no extra balance or return. You can skip linking if there's no reliable source.",
  "关联付款计划在最近删除中。": "The linked payment plan is in Recently Deleted.",
  "关联付款计划在最近删除中，可在电脑上恢复或核对。": "The linked payment plan is in Recently Deleted. Restore or check it on a computer.",
