  "关联的付款计划已在最近删除；请明确选择将它归入同一删除组": "The linked payment plan is already in Recently Deleted; explicitly choose to include it in the same deletion group",
  "关联的服务档案在最近删除中：可恢复档案形成有效组，或删除剩余计划并归成一组。": "The linked service record is in Recently Deleted: restore the record to form a valid group, or delete the remaining plans and consolidate them into one group.",
