  "其他负债": "Other liabilities",
  "其他账户沿用已有金额，没有金额的仍为未知。增减填正数或负数，结果不能小于 0。转账仅支持金额已知、币种及计入范围相同的账户。": "Other accounts use existing amounts; accounts without an amount remain unknown. Enter increases as positive numbers or decreases as negative numbers; the result cannot be less than 0. Transfers are only supported between accounts with a known amount, the same currency, and the same inclusion scope.",
  "其他资产": "Other assets",
  "养老金": "Pension",
  "养老金也只使用你从官方工具获取后填写的金额和月份，不计算资格、待遇或缴费变化。原有账户与盘点不会被更改。": "Pension also uses only the amounts and months you obtain from the official tool and enter; it does not calculate eligibility, benefits, or contribution changes. Your existing accounts and check-ins will not be changed.",
  "养老金事实": "Pension facts",
  "养老金只使用已填写的金额与月份，不测算待遇、资格或缴费变化。固定账面金额会随通胀贬值；结束月仍计入。": "Pension uses only the entered amounts and months and does not project changes in benefits, eligibility, or contributions. The fixed book value will be eroded by inflation; the final month is still included.",
