  "净资产端点只取真实完整盘点；净资产不是包含房产的家庭总资产。收入、重要支出与退款按原来源口径读取。": "Net worth endpoints use only actual full check-ins; net worth is not total household assets including property. Income, major expenses, and refunds are read on their original-source basis.",
  "净资产端点只取真实完整盘点；起点取窗口开始日当天或之前的最近完整盘点，缺失时取区间内首次完整盘点；终点取区间内最近完整盘点。净资产不是包含房产的家庭总资产。收入、重要支出与退款按原来源口径读取，各区块独立降级。": "Net worth endpoints use only actual full check-ins. The start point is the most recent full check-in on or before the window start date; if none exists, use the first full check-in in the range. The end point is the most recent full check-in in the range. Net worth is not total household assets including property. Income, major expenses, and refunds are read on their original-source basis, and each section falls back independently.",
