  "刚从加密备份恢复，本机没有可用的加密策略。自动与额外备份保持暂停，直到你确认后续备份方式。": "You just restored from an encrypted backup, and no encryption policy is available on this device. Automatic and extra backups stay paused until you confirm how future backups should work.",
