  "删除分组": "Delete Group",
  "删除后不可恢复，已保存物品不受影响。": "Deletion cannot be undone. Saved items are unaffected.",
  "删除后不能恢复，已保存物品的图片不受影响。": "Deletion cannot be undone. Images for saved items are unaffected.",
  "删除后物品及关联记录从各处隐藏，可在“最近删除”中恢复。已经不用请选退役，卖掉了请选记录售出。": "Deleting hides the item and related records everywhere; you can restore them from Recently Deleted. If you no longer use it, choose Retire. If you sold it, choose Record Sale.",
  "删除后，{accounts} 个账户会变成未分组，账户本身不会删除。此操作无法撤销；重新建组后仍需重新分配账户。": "After deletion, {accounts} account(s) will become ungrouped; the accounts themselves won't be deleted. This cannot be undone. If you recreate the group, you'll still need to reassign the accounts.",
  "删除存钱目标": "Delete Savings Goal",
