  "删除物品…": "Delete Item…",
  "删除物品记录": "Delete Item Record",
  "删除用于录错或重复的记录。这些物品及它们的维护、保障、关联支出会从各处隐藏，可从“最近删除”逐件恢复。已经不用、送人或丢失了？请改用“退役”；卖掉了请用“售出”。": "Delete records that were entered by mistake or are duplicates. These items, along with their maintenance, coverage, and linked expenses, will be hidden throughout the app. You can restore them one at a time from Recently Deleted. No longer need it, gave it away, or lost it? Use Retire instead. Sold it? Use Sold.",
  "删除用于录错或重复的记录。这件物品及它的维护、保障、关联支出会从各处隐藏，资料和图片保留，之后可以从“最近删除”恢复。已经不用、送人或丢失了？请改用“退役”；卖掉了请用“售出”，这样历史会保留。": "Use Delete for records entered by mistake or duplicated. The item and its maintenance, protection, and related expenses are hidden everywhere. Details and photos are kept and can be restored later from Recently Deleted. No longer need it, gave it away, or lost it? Choose Retire instead. Sold it? Choose Record Sale so history is preserved.",
