  "利息与现金分红用于核对收入构成，不重复加到投资损益。未关联账户的记录保留在未归属明细。": "Interest and cash dividends are used to reconcile income composition and are not double-counted in investment gains and losses. Records not linked to an account remain in unassigned details.",
  "到": "To",
  "到{name}测算 ↗": "Go to {name} Projection ↗",
  "到哪一期": "Through Which Period",
  "到手工资扣掉所有花销、社保之后，每月剩下能存下来的钱，可以是 0 或负数。不计尚不能提取的公积金缴存；稳定提取若已算在净存入中，不要再填作未来收入。填了才能对比。": "This is the amount left to save each month after deducting all expenses and social insurance from take-home pay. It can be 0 or negative. Do not count housing provident fund contributions that cannot yet be withdrawn. If stable withdrawals are already included in net contributions, do not enter them again as future income. Required for comparison.",
