  "到账 {v1}": "Credited {v1}",
  "到账减去全部开销后剩下的钱；买基金等投入也算，投资涨跌不算。空白是未知，0 表示不存钱，负数表示取用存款。": "Money left after subtracting all spending from income received; money put into funds and similar investments also counts as spending, while investment gains and losses do not. Blank means unknown, 0 means no saving, and a negative number means drawing on savings.",
