  "填好出生年月后，直接填写退休年龄和规划终点年龄；也可以在下方按月份填写。": "After entering your birth date, enter your retirement age and planning end age directly; you can also enter them by month below.",
  "填好开始日期和每期金额后会按周期生成": "Once the start date and per-period amount are set, periods will be generated automatically.",
