  "填好每月能存的钱后，这里显示资产轨迹。逐年表、压力测试与市场模拟在「测算详情」。": "After entering how much you can save each month, your asset trajectory will appear here. The year-by-year table, stress test, and market simulation are in Projection Details.",
  "填好金额和开始日期后，这里会列出将生成的每一期；到期日须晚于开始日期。": "After you enter the amount and start date, each period to be generated will be listed here; the due date must be later than the start date.",
