  "存在多条有效售出记录，请重试或先更正售出记录": "Multiple valid sale records exist; please try again or correct the sale records first",
  "存在未支持情形时不能确认简单损益完整，可保存备注后待复核": "When unsupported cases exist, simple gain/loss cannot be confirmed complete; save a note and leave it pending review",
  "存在未支持情形时不能确认简单损益完整，可保存备注后待复核。": "When unsupported cases exist, simple gain/loss cannot be confirmed complete; save a note and leave it pending review.",
