  "存钱目标": "Savings goal",
  "存钱目标 {v1}": "Savings goal {v1}",
  "存钱目标 {v1} 个": "Savings goals: {v1}",
  "存钱目标 · 当前进度": "Savings goal · Current progress",
  "存钱目标 ↓": "Savings goal ↓",
  "存钱目标显示最近完整盘点的当前进度，不随回顾区间重算，余额达标不等于资金已经预留。退休规划是当时针对盘点留下的结论；旧记录没有引擎版本，不声称模型口径始终一致。": "Savings goal shows current progress from the most recent full check-in and is not recalculated with the review period; reaching the balance target does not mean the funds are set aside. Retirement planning reflects the conclusions drawn from that check-in at the time; older records have no engine version, so we do not claim the model assumptions have always been consistent.",
  "存钱目标读取失败：{error}": "Failed to load savings goal: {error}",
  "存钱目标需要关联一个可用的资产账户。先添加账户，再设置目标；房产和负债不能关联。": "A savings goal must be linked to an available asset account. Add an account first, then set the goal; property and liabilities cannot be linked.",
  "存钱目标：{note}": "Savings goal: {note}",
  "存钱阶段": "Savings phase",
  "季": "Quarter",
  "季付": "Quarterly",
  "孩子出生年月": "Child's birth month",
  "孩子出生年月（换算用）": "Child's birth month (for conversion)",
  "它们仍在标签中，但不参与本页的投入与占比。可回物品列表处理「不计入统计」开关。": "They are still in the tag but do not count toward this page's contributions or percentages. Go back to the item list to change the \"Exclude from stats\" toggle.",
  "它是按你填的数字做的估算，不是预测：不会替你猜会不会被裁、多久找到工作、工资涨不涨。每月付款的先后只在不工作那一段检查过。未来收入与暂时取不出的钱是否计入，以答案旁的本次假设为准；公积金周期缴存、提取与余额耗尽尚未推演。": "This is an estimate based on the numbers you entered, not a prediction: it will not guess whether you will be laid off, how long it will take to find work, or whether your salary will rise. The order of monthly payments was checked only for the period when you are not working. Whether future income and temporarily unavailable funds are counted depends on the assumptions shown next to each answer; recurring housing fund contributions, withdrawals, and balance depletion are not yet modeled.",
  "它的关联对象也在最近删除；请在最近删除中整组恢复，或在核对中登记为一组": "Its linked counterpart is also in Recently Deleted; restore the whole group from Recently Deleted, or register them as a group during reconciliation",
  "完成": "Done",
  "完成一次完整盘点后显示金融净资产": "Financial net worth appears after one full check-in",
  "完成两次完整盘点后可比较": "Comparison is available after two full check-ins",
