  "完成两次完整盘点后，这里会把净资产变化和同一区间的收入、支出放在一起看。": "After two full check-ins, this shows net worth changes alongside income and spending for the same period.",
  "完成两次盘点后，可以选择日期比较。": "After two check-ins, you can choose dates to compare.",
  "完成目标设置后可查看": "Available after you set a goal",
