  "完整": "Full",
  "完整 · 范围变化": "Full · Scope changed",
  "完整备份": "Full Backup",
  "完整备份包含物品、维护、保障、心愿、账户与盘点、支出、周期计划、虚拟资产、分类渠道、素材、最近删除及托管原图，可用于恢复。恢复前会检查所选备份，并保护当前资料。": "A full backup includes items, maintenance, coverage, wishes, accounts and check-ins, expenses, recurring plans, virtual assets, categories and channels, media, Recently Deleted, and hosted originals, and can be used to restore. Before restoring, the selected backup is checked and your current data is protected.",
  "完整备份包含物品、维护、保障、心愿、账户与盘点、重要支出与退款、周期计划与付款、虚拟资产、分类渠道、素材、最近删除及托管原图，可用于恢复。恢复前会检查所选备份，并保护当前资料。": "A full backup includes items, maintenance, coverage, wishes, accounts and check-ins, major expenses and refunds, recurring plans and payments, virtual assets, categories and channels, media, Recently Deleted, and hosted originals, and can be used to restore. Before restoring, the selected backup is checked and your current data is protected.",
  "完整备份并异地保存": "Full Backup and Save Offsite",
  "完整性": "Completeness",
  "完整条件": "Completeness Criteria",
  "完整生活预算／月": "Full Living Budget/Month",
