  "完整盘点不足两次，暂无较期初变化": "Fewer than two full check-ins, so no change from the starting point yet",
  "完整目标余额不足两次，暂不画趋势。": "Fewer than two full goal balances, so no trend yet.",
  "完整组余额与历史含义（{length} 个账户）": "What the full group balance and history mean (Accounts: {length})",
  "完整表示应盘账户都有金额；含沿用金额不代表全部重新核对。金额缺项时不展示净资产合计。": "Full means every account due for a check-in has an amount; carried-over amounts do not mean everything was re-verified. The net worth total is not shown if any amount is missing.",
  "完整表示应盘账户都有金额；快速更新可能沿用旧值，不代表全部重新核对。": "Full means every account due for a check-in has an amount; a quick update may reuse old values and does not mean everything was re-verified.",
  "完整预算金额无效": "Full budget amount is invalid.",
  "完整预算（当前设置）": "Full Budget (Current Settings)",
  "官方工具的测算结果或其他手填收入假设；不在本应用计算领取资格。": "Projection results from official tools or other manually entered income assumptions; this app does not calculate eligibility.",
