  "实付未知": "Amount Paid Unknown",
  "实付未知就留空，不会记成 0；到账额度默认为实付加赠送。": "If the amount paid is unknown, leave it blank; it will not be recorded as 0. The credited amount defaults to amount paid plus bonus.",
