  "实际收到的净额；没有到账就填 0": "Net amount actually received; enter 0 if none arrived",
  "实际收到的净额；转入本金不属于收入，账户涨跌也不记在这里": "Net amount actually received; principal transfers are not income, and account gains and losses are not recorded here",
  "实际收益已扣除通胀。0% 表示购买力不变，不是银行利息为零；未来收益属于假设。": "Real returns are adjusted for inflation. 0% means purchasing power is unchanged, not that bank interest is zero; future returns are assumptions.",
  "实际收益已扣除通胀。默认收益 0% 只代表跑平通胀；默认波动率是程序试算值。": "Real returns are adjusted for inflation. The default 0% return only means keeping pace with inflation; the default volatility is calculated by the app for illustration.",
  "实际收益率": "Real Return Rate",
  "实际收益输入超出合法范围。": "Actual return is outside the valid range.",
  "实际收益默认 0%，表示钱只跑平通胀；默认波动率 5% 是程序试算值，不是资产配置的风险估计。收益、通胀和波动率在独立的「假设核对」编辑器里修改和确认；编辑预算、投入等其他分区只会原样携带这些值，不会顺带确认。": "The default real return is 0%, meaning money only keeps pace with inflation; the default volatility of 5% is calculated by the app for illustration, not a risk estimate for your asset allocation. Return, inflation, and volatility are edited and confirmed in the separate \"Assumptions Check\" editor; editing budgets, contributions, or other sections only carries these values over as-is and does not confirm them.",
  "实际日期须不晚于今天。": "The actual date cannot be later than today.",
