  "对比目标需要存的钱和你实际估计能存的钱，不影响先看需求。": "Compare the amount the goal requires you to save with what you actually expect to save; this does not affect viewing needs first.",
  "对照变化月": "Monthly Change Comparison",
  "对照各平台填写当前金额，零余额填 0。上次金额只作参考。": "For each platform, enter the current amount; enter 0 for a zero balance. The previous amount is for reference only.",
  "对照各平台，把今天的余额和欠款逐行填进来。之后每次盘点都会成为趋势上的一个点。": "For each platform, enter today's balances and debts line by line. Each later check-in becomes a point on the trend.",
  "对照所选日期填写每个账户的余额或欠款，确定是零就填 0，不知道的金额不要填成零。余额没有变化时，点「与上次相同」即可确认。回车跳到下一行；填齐后保存，关闭即放弃未保存的输入。": "Enter the balance or amount owed for each account as of the selected date. If it's definitely zero, enter 0. If you don't know an amount, don't enter 0. If the balance hasn't changed, tap \"Same as last time\" to confirm. Press Enter to move to the next row. Save when everything is filled in; closing discards unsaved input.",
