  "导入回执格式无效": "Invalid import receipt format",
  "导入备注：{v1}": "Import note: {v1}",
  "导入工作簿最多 50000 数据行、32 列；请移除范围外的单元格和格式": "The import workbook can have up to 50000 data rows and 32 columns; remove any cells and formatting outside that range.",
  "导入已有的资产表格": "Import Existing Asset Spreadsheet",
  "导入映射 ID 无效": "Invalid import mapping ID",
  "导入映射 {v1} 条": "Import mappings: {v1}",
  "导入映射格式无效": "Invalid import mapping format",
  "导入映射类型无效": "Invalid import mapping type",
  "导入未提交，资料未改变：": "Import not submitted; data unchanged:",
  "导入步骤": "Import Steps",
  "导入物品表只新增物品，不修改或合并已有物品，不能用于批量修改；只有名称必填，状态为已退役须填退役日期，已售出须填售出日期与售价。名称、购入日期和购入价与已有物品或文件内其他行相同会判为疑似重复，默认跳过。导出工作簿的「物品」工作表也可以直接导入；金融历史入口读取「账户」「完整盘点」「月度收入」。物品或金融导入提交后结果未知时，上次操作的编号都会保留，点「核对物品导入结果」或「核对金融导入结果」只检查上次导入是否成功，不会再次写入资料，确认未提交后才重新导入。整体搬家或回到以前请用完整备份。": "Item import only adds items. It does not modify or merge existing items, and bulk edits aren't supported. Only the name is required. For retired items, enter the retirement date; for sold items, enter the sale date and sale price. Rows with the same name, purchase date, and purchase price as an existing item or another row in the file are treated as possible duplicates and skipped by default. The “Items” sheet in an exported workbook can also be imported directly; Financial History import reads the “Accounts,” “Full Check-ins,” and “Monthly Income” sheets. If an item or financial import has an unknown result after submission, the previous operation ID is kept. Clicking “Check Item Import Result” or “Check Financial Import Result” only checks whether the last import succeeded; it doesn't write data again. Re-import only after confirming that it wasn't submitted. To move all data or return to an earlier state, use a full backup.",
  "导入物品表（Excel）": "Import Items (Excel)",
  "导入结果分页": "Import Results Pagination",
  "导入结果未知：": "Import result unknown:",
  "导入请在原生 App 验证。": "Import must be verified in the native app.",
  "导入金融历史（Excel）": "Import Financial History (Excel)",
  "导入：{v1}": "Import: {v1}",
  "导出…": "Export…",
  "导出失败，请重试。": "Export failed. Please try again.",
  "导出并分享表格": "Export and Share Spreadsheet",
  "导出当前报告": "Export Current Report",
  "导出文件名无法读取": "Could not read the export filename.",
  "导出文件必须位于 App 的 Documents 目录": "The export file must be in the app's Documents directory.",
  "导出未加密副本…": "Export Unencrypted Copy…",
  "导出未完成：": "Export incomplete:",
  "导出的表格不是备份，不能用来恢复。要保护资料，请使用「数据管理」里的完整备份。": "The exported spreadsheet is not a backup and can't be used to restore. To protect your data, use a full backup in Data Management.",
  "导出结果未返回，请到 Documents 核对": "No export result was returned. Check the Documents directory.",
  "导出表格": "Export Spreadsheet",
  "导出资料表格保存为一个 .xlsx 文件，各类数据分工作表；其中物品、账户、完整盘点与月度收入可在对应入口预览导入，只有部分工作表支持导入，盘点记录、重要支出与周期费用等其余表仅供查看分析。文字、编号、日期和金额按文本保存，空金额仍为未知。Excel 不能用于恢复全部资料。最近删除仅用于找回误删记录。": "The data spreadsheet is exported as a single .xlsx file with each data type on its own sheet. Items, accounts, full check-ins, and monthly income can be previewed for import from their respective screens, but only some sheets support import. The remaining sheets, such as check-in records, major expenses, and recurring costs, are for viewing and analysis only. Text, IDs, dates, and amounts are stored as text, and blank amounts remain unknown. Excel can't be used to restore all data. Recently Deleted is only for recovering accidentally deleted records.",
  "导出资料表格（Excel）": "Export Data Spreadsheet (Excel)",
  "封面 · ": "Cover · ",
  "封面必须是当前选择的图片": "The cover must be the currently selected image.",
  "将「{asset_name}」的服务档案与关联付款计划「{plan_name}」一起移入最近删除。": "Move the service record for “{asset_name}” and its linked payment plan “{plan_name}” to Recently Deleted.",
  "将一起恢复「{asset_name}」服务档案与付款计划「{plan_name}」，原 ID 与历史付款保持不变。": "The “{asset_name}” service profile and payment plan “{plan_name}” will be restored together; the original ID and payment history will remain unchanged.",
  "将于 {date} {v2}": "Will {v2} on {date}",
  "将从「": "This will change from “",
  "将剩余有效对象一并移入最近删除，登记为可整组恢复的删除组。": "The remaining valid objects will be moved to Recently Deleted and recorded as a deletion group that can be restored as a whole.",
  "将恢复为上段已结束的订阅。旧期间与旧付款保持原样；不会取消服务方的订阅或办理退款。": "It will be restored as a subscription whose previous period has ended. Existing periods and payments will remain unchanged; this won't cancel the subscription with the service provider or issue a refund.",
  "将新建分类：{v1}": "Will create category: {v1}",
  "将新建的分组：{v1}。仅在确认导入整批后保存。": "Groups to be created: {v1}. They'll be saved only after you confirm the entire batch import.",
  "将新建购买渠道：{v1}": "Will create purchase channel: {v1}",
  "将更改": "Will change",
  "将未来的金额换算回今天的购买力，使金额与你当前的预算具有可比性。": "Converts future amounts back to today's purchasing power so they're comparable with your current budget.",
  "将永久清除最近删除里的全部内容，不可恢复。其中关联订阅 {length} 组，其他 {other_count} 项。由心愿实现的物品需先永久删除对应心愿，会被保留。": "This will permanently delete everything in Recently Deleted and can't be undone. This includes {length} linked subscription group(s) and {other_count} other item(s). Items created from wishes are kept until you permanently delete the corresponding wish.",
  "将永久移除「{asset_name}」服务档案、付款计划「{plan_name}」及以下全部事实，删除后无法找回：": "This will permanently remove the “{asset_name}” service profile, the “{plan_name}” payment plan, and all of the following records. This can't be undone:",
