  "工作阶段月内付款未完整检查。结果是按所填条件计算的估算，不是职业预测或保证；当前仍为待验证的独立原型。": "Monthly payments during the working phase were not fully checked. Results are estimates based on the entered conditions, not career predictions or guarantees; this is still an independent prototype pending validation.",
