  "已确认分组已保存，账户输入仍保留。": "Group save confirmed; account entries are still kept.",
  "已确认在最新版本上保留你的输入，请核对后保存。": "Your input has been confirmed and kept on the latest version. Please review, then save.",
  "已确认完整时金额必须明确：未知请先留空并取消确认，零必须显式填 0": "When confirming as complete, the amount must be clear: leave blank and uncheck confirmation if unknown; enter 0 explicitly for zero",
  "已确认尚未购入，回到考虑中；旧版生成的物品仍在档案中。": "Confirmed as not yet purchased and moved back to considering; the item created by the older version is still in your records.",
  "已确认才计入重要支出。点已记录的期次可更正金额、日期或改回待确认。": "Only confirmed entries count as major expenses. Tap a recorded period to correct the amount or date, or set it back to pending confirmation.",
