  "已确认这次没有导入，整批资料都没有写入。": "Confirmed: nothing was imported this time; none of the batch data was written.",
  "已算入的部分够用，还有事项需确认": "What's included so far is enough, but some items still need confirmation",
  "已纳入条件在所选有限期间可覆盖；仍有影响计算的待核对项": "Included terms can be covered within the selected limited period; there are still unverified items affecting the calculation",
  "已纳入规划的自有投资，其利息和分红包含在总回报假设里，不要在这里重复添加。这里只填养老金、租金等另外的净收入。": "Interest and dividends on your own investments already in the plan are included in the total return assumption—don't add them again here. Only enter separate net income such as pensions and rent.",
  "已经切换资料，上次操作编号仍保留。请回到原来的资料中核对，不要在这里重复导入同一文件。": "Profile already switched; the last operation ID is still kept. Go back to the original profile to verify, and don't import the same file again here.",
  "已经切换资料，上次操作编号仍保留。请回到原来的资料核对，也可检查当前资料是否保留了同一次导入的成功记录；核对不会写入资料，不要在这里重复导入。": "You've switched data sets, and the ID from your last action is still kept. Go back to the original data set to check, or see whether the current one kept the success record from the same import. Checking won't write any data, so don't import again here.",
