  "应用中默认沿用原计划的未来收入与已确认资金释放；若换工作会改变它们，请在这里调整本次条件。定期公积金缴存与提取尚未单独推演，不要把缴存当现金收入。": "The app uses the original plan's future income and confirmed fund releases by default. If a job change would alter them, adjust this scenario's conditions here. Regular provident fund contributions and withdrawals are not modeled separately; do not count contributions as cash income.",
