  "当前持有物品（使用中＋已退役）各自的日均成本之和：每件（购入价＋维护费）÷持有天数，四舍五入到分后相加。已售出、已删除、按次计费与设为不计入日均的物品不参与；资料不全不当作零。总金额和统计页的排除选项不影响日均。此数值是持有成本的摊算，不是每天实际支出，不含金融账户、订阅或房租。": "The sum of the daily costs of currently owned items (in use + retired): for each item, (purchase price + maintenance cost) ÷ days owned, rounded to the nearest cent and then added. Sold, deleted, per-use, and items excluded from daily cost are not included; incomplete data is not treated as zero. The total amount and exclusion options on the stats page do not affect the daily cost. This value is an amortization of ownership cost, not actual daily spending, and excludes financial accounts, subscriptions, or rent.",
