  "恢复指针无效": "Restore pointer is invalid",
  "恢复时会保留物品、账户、盘点及实际发生记录；旧退休政策资料会移除，规划时间和未来收入请重新确认。": "Restoring keeps items, accounts, check-ins, and actual records; old retirement policy data will be removed, so re-confirm planning dates and future income.",
  "恢复时间未知": "Restore time unknown",
  "恢复时间未知，请选择局部检查的结束月份。": "The resumption date is unknown. Select the end month for the partial check.",
  "恢复时间未知；仅检查明确的空窗期间，不计算长期目标需求。": "The resumption date is unknown; only confirmed gap periods are checked, and long-term goal needs are not calculated.",
  "恢复晚于原目标；空窗检查仅覆盖到目标月之前。": "The resumption date is later than the original goal; the gap check only covers the period before the goal month.",
