  "悬浮查看详情 · 点击固定 · 方向键切换期间": "Hover for details · Click to pin · Arrow keys switch periods",
  "情景": "Scenario",
  "想买的理由与顾虑": "Reasons to buy and concerns",
  "想按年龄填写开始时间时，先在时间安排里确认年龄参考。": "To set the start time by age, first confirm the age reference in the schedule.",
  "想看未来的钱够不够，可以先试一个每月能存下的金额。还没想好也没关系，上面的目标需求仍可查看。": "To see whether you'll have enough in the future, try a monthly savings amount. It's okay if you haven't decided—you can still view the goal requirements above.",
  "想知道什么": "What do you want to know?",
  "想知道被裁、辞职歇一阵能撑多久，或换成每月攒得少的工作要不要晚几年退休？填几个数就有答案。结果只在这次试算里，不会改你的目标和资料。": "Want to know how long you could last if you were laid off or took a break from work, or whether switching to a job where you save less each month would mean retiring a few years later? Enter a few numbers to find out. Results stay in this what-if and won't change your goals or profile.",
  "想知道：要攒多少钱才够？": "Want to know: How much do I need to save?",
  "成员必须是对象": "Members must be objects",
  "成本": "Cost",
  "成本计算模式": "Cost Calculation Mode",
  "我们根据你的假设模拟不同市场路径。阴影显示各月份的第 10 至第 90 百分位区间；线条显示各路径的中位数，并非单一路径。收益取扣除通胀后的实际收益，围绕假设值按波动率 {v1} 随机，每年一次，固定种子，同一计划每次结果一致。": "We simulate different market paths based on your assumptions. The shaded area shows the 10th to 90th percentile range for each month; the line shows the median across paths, not a single path. Returns are real, net of inflation, and randomized around the assumed value using volatility {v1} once a year with a fixed seed, so the same plan produces the same results every time.",
  "我已核对这些假设（选填）": "I've reviewed these assumptions (optional)",
  "我想歇一阵，能撑多久？": "If I take a break, how long can I last?",
  "我现在一共有多少钱？这几个月变了多少？": "How much do I have in total now? How much has it changed over the past few months?",
