  "我确认所选范围确实已付，每期金额如上": "I confirm that the selected range was actually paid, at the per-period amounts shown above.",
  "我确认本次尚未建立保护备份，仍继续导入": "I confirm that no protection backup has been created yet and want to continue the import.",
