  "截至 {date} · 余额": "As of {date} · Balance",
  "截至 {date} 可用 {v2}（": "As of {date}, available {v2} (",
  "截至 {date} 完整盘点 · 距今 {daysSince} 天": "Full check-in as of {date} · {daysSince} day(s) ago",
  "截至 {date} 完整盘点 · 距今 {v2} 天{v3}": "Full check-in as of {date} · {v2} day(s) ago{v3}",
  "截至 {date} 的完整盘点。可用资金包括现金、存款和准备变现用于本计划的基金、证券等投资，按盘点价值及参与比例计入，不改变实际余额。新增现金及投资账户先建议可动用，请逐项确认；有锁定期、不能赎回或不准备动用的资产，改为暂不能动用或本计划不参与。": "Full check-in as of {date}. Available funds include cash, deposits, and investments such as funds and securities that you plan to cash out for this plan. They are counted at check-in value and in proportion to participation, without changing your actual balance. New cash and investment accounts are initially suggested as available. Please confirm each one. If an asset has a lock-up period, can't be redeemed, or won't be used, change it to temporarily unavailable or excluded from this plan.",
  "截至 {date}的盘点名义金额{v2}。": "Nominal check-in amount as of {date}: {v2}.",
