  "截至 {recorded_on}": "As of {recorded_on}",
  "截至 {today} 的持有物购入金额，包含使用中与已退役物品；不是当前估值，不与金融净资产相加。": "Purchase cost of items held as of {today}, including items in use and retired. This is not current value and is not added to financial net worth.",
