  "房产": "Property",
  "房产仅单独记录估值，不能计入金融净资产": "Property value is recorded separately and cannot be counted toward financial net worth.",
  "房产仅单独记录当前估值，不计入金融净资产；有效期间仍需在每次完整盘点确认金额。房贷仍独立记录，金融净资产不代表包含房产的家庭总资产。": "Property value is tracked separately and excluded from financial net worth; while active, confirm the amount at every full check-in. Mortgages remain separate; financial net worth is not total household assets including property.",
