  "把买断的软件、注册的域名、订阅的服务和储值卡记下来，就能看到它们的计费方式、什么时候到期、一共花了多少。": "Record the software you bought outright, domains you registered, services you subscribe to, and stored-value cards to see how they're billed, when they expire, and how much you've spent in total.",
  "把各平台的余额和欠款录一遍，看到净资产": "Record balances and debts across platforms to see your net worth",
  "把已有表格搬进来，只新增物品、不修改已有记录，不能用于批量修改；导入前先预览。": "Import an existing spreadsheet to add new items only without changing existing records; bulk edits aren't supported. Preview before importing.",
  "把房和车算进来：每件拆成一次性现金支出（首付、杂费、换车净支出）和持续的月度收支（月供、持有成本、不再付的房租），并入同一个退休计算。「日常生活」预算请不要再含房租、房贷和车。这里只估算，不扣你真实的资产，也不划拨。": "Include your home and car: split each into one-time cash outlays (down payment, fees, net cost of replacing the car) and ongoing monthly cash flow (mortgage, ownership costs, rent you no longer pay), then combine them in the same retirement calculation. Leave rent, mortgage, and car costs out of your \"Everyday Living\" budget. This is an estimate only; it doesn't deduct from or allocate your actual assets.",
  "把房租、订阅、保险这类定期付的钱记成计划，就能看到每年的固定负担和下次什么时候付。": "Record recurring costs like rent, subscriptions, and insurance as plans to see your fixed annual burden and when the next payment is due.",
  "把物品、账户、盘点、支出和周期费用导出成一份 Excel 工作簿，用来在电脑上查看或自己分析。表格导入和投资资金流动核对请在电脑版进行。": "Export items, accounts, check-ins, expenses, and recurring costs as an Excel workbook to view or analyze on your computer. Spreadsheet import and investment cash flow reconciliation are available on desktop.",
  "把这项计划与虚拟资产里的服务档案关联：只新增档案，已有付款与排期保持原样。": "Link this plan to a service profile in virtual assets: only new profiles are added; existing payments and schedules remain unchanged.",
