  "按上方账户范围显示；合计始终包含整个比较区间。停用账户有余额变化或金额尚未确认时仍显示。": "Displayed by the account scope above; totals always cover the entire comparison period. Inactive accounts still appear if their balance changed or amounts are pending confirmation.",
  "按今天物价": "In today's prices",
  "按今天物价填写。应急金是参考线，不另从退休资金扣除。": "Enter in today's prices. The emergency fund is a reference line and is not deducted from retirement funds separately.",
  "按今天的物价，吃饭、住房、日常开销合计；按全家规划就填全家的。": "At today's prices, total food, housing, and daily expenses; if planning for the whole family, enter the family total.",
