  "按你估计的每月能攒多少": "Based on your estimated monthly savings",
  "按你假设的复工后储蓄，检查现金与原退休目标；不是只看存款能花多久": "Checks cash and the original retirement goal based on your assumed post-return-to-work savings; not just how long your savings will last",
