  "正序": "Ascending",
  "此功能已关闭，请启用后重新打开。": "This feature is off. Enable it and reopen.",
  "此名称由系统保留": "This name is reserved by the system",
  "此后保持同样购买力": "Maintain purchasing power thereafter",
  "此后金额不自动增长": "Amount does not grow automatically thereafter",
  "此处为固定虚构输出，未保存。真实投资核对须在原生应用中进行。": "This is fixed mock output and is not saved. Real investment reconciliation must be done in the native app.",
  "此处显示适合窗口的预览，原图保留在本机。": "A preview sized to fit the window is shown here; the original stays on this device.",
  "此日之前的盘点不要求填写": "Check-ins before this date are not required",
  "此标签仅用于实物，请在标签管理中改为通用后再选择": "This tag is for physical items only. Change it to general in tag management before selecting it.",
  "此标签在另一领域仍有引用；请先迁移或清空那些引用，再收窄适用范围": "This tag is still referenced in another area. Migrate or clear those references before narrowing its scope.",
  "此盘点尚有未知余额，先补齐完整盘点": "This check-in still has unknown balances. Complete a full check-in first.",
  "此类型新建建议：{v1}": "Suggested new name for this type: {v1}",
  "此计划已关联其他虚拟资产": "This plan is already linked to another virtual asset",
  "此请求不是金融导入": "This request is not a financial import",
  "此请求标识已用于不同内容": "This request identifier has already been used for different content",
  "步骤 {v1} / 5{v2}": "Step {v1} / 5{v2}",
  "每 2 个月": "Every 2 months",
  "每 3 个月": "Every 3 months",
  "每 {interval_days} 天": "Every {interval_days} day(s)",
  "每 {interval_days} 天一期": "One period every {interval_days} day(s)",
  "每 {n} 个月": "Every {n} month(s)",
  "每一行是「如果买下」的影响，只算这一件（其他心愿不发生）。合计只计入填了计划日期、也就是打算买的；没填日期的只作「如果今天买」的假设，不进合计；计划日期已过的不计入，更新日期后重新估算；没填预计价格的无法估算。这些只是估算，不扣你真实的资产，不改变心愿的状态，也不替代「已买到，记录购入」；还没决定的心愿不要填计划日期，价格建议填偏保守的。": "Each row shows the impact of buying that item, counting only that item (other wishes do not happen). The total includes only wishes with a planned date, meaning you intend to buy them; wishes without a date are treated as a “buy today” what-if and are not included; past planned dates are excluded, so update the date to recalculate; items without an estimated price cannot be estimated. These are estimates only: they do not deduct from your actual assets, change wish status, or replace “Bought, record purchase.” Do not set a planned date for wishes you have not decided on, and keep price estimates on the conservative side.",
  "每个币种新增金额时默认带出的汇率。": "The exchange rate pre-filled by default when adding an amount in each currency.",
  "每个情景只改一件事，其余假设不变，用同一套计算重新推演。期末剩余资金在以不靠工资为目标时可能因推迟退休而更多，所以请和财务独立月份一起看。": "Each scenario changes only one thing while keeping all other assumptions the same, rerunning the same calculations. End-of-period funds may be higher when retirement is delayed if your goal is not relying on a salary, so view it together with your financial independence month.",
  "每件各添加一份保障：默认从购入日期起一年，购入日期未知时从今天起；表头可统一类型与年限。": "Add one coverage plan for each item: one year from purchase date by default, or from today if the purchase date is unknown; use the header to set one type and term for all.",
  "每件物品归入一个分类，用来筛选和统计。拖动左侧手柄或点上下箭头调整顺序，选择分类时按此顺序列出。": "Each item belongs to one category, used for filtering and stats. Drag the left handle or tap the up/down arrows to reorder; categories are listed in this order when choosing one.",
  "每件物品最多 20 张图片，不能重复选择": "Up to 20 images per item; duplicates cannot be selected",
  "每半年": "Every 6 months",
  "每单位原币兑换的人民币，只用于本次修改金额的账户；未改动的历史金额保留各自汇率。不联网取汇率。": "The RMB per unit of original currency applies only to accounts whose amounts you change now; unchanged historical amounts keep their respective exchange rates. Exchange rates are not fetched online.",
  "每季": "Quarterly",
  "每年": "Yearly",
  "每年上涨请填 -10 到 20 之间的百分数，或留空跟随通胀。": "For annual increase, enter a percentage between -10 and 20, or leave blank to follow inflation.",
  "每年上涨须为 -10 到 20% 之间，留空跟随通胀。": "Annual increase must be between -10 and 20%; leave blank to follow inflation.",
  "每年上涨（%）": "Annual increase (%)",
  "每年从已有资金中取用": "Withdraw from existing funds each year",
  "每年从已有资金中取用的比例：{v1}": "Annual withdrawal rate from existing funds: {v1}",
  "每年投入": "Annual contribution",
  "每张图片不得超过 20 MiB。": "Each image must not exceed 20 MiB.",
  "每批总大小最多 20 MiB，请拆分文件": "Each batch can be at most 20 MiB total; please split the files.",
  "每批数据行合计最多 50000，请拆分文件": "Each batch can contain at most 50000 data rows in total; please split the file.",
  "每月": "Monthly",
  "每月 {v1} × {months} 个月 = {v3}，不是剩余本金。": "Monthly {v1} × {months} month(s) = {v3}, not the remaining principal.",
  "每月一共能存": "Total you can save each month",
  "每月一次，看清家底": "Once a month, see your full financial picture.",
  "每月估计现金存下（中位数）：": "Estimated monthly cash saved (median):",
  "每月余量约": "Approx. Monthly Surplus",
  "每月全部开销": "Total Monthly Expenses",
  "每月养车费": "Monthly Car Costs",
  "每月养车费（保险、停车、充电或油费、保养）": "Monthly car costs (insurance, parking, charging or fuel, maintenance)",
  "每月净投入": "Net Monthly Contribution",
  "每月到账": "Monthly Inflow",
  "每月到账减去全部开销后剩下的钱。买基金等投入也算，投资涨跌不算；取用存款填负数。只试算不会保存。": "Money left after subtracting all expenses from monthly inflows. Fund purchases count as contributions, but investment gains and losses do not. Enter a negative number when drawing from savings. What-if only; nothing is saved.",
  "每月到账减去全部开销后剩下的钱。取用存款填负数；填 0 只表示本次按每月不存钱计算。": "Money left after subtracting all expenses from monthly inflows. Enter a negative number when drawing from savings; entering 0 only means this calculation assumes no monthly saving.",
  "每月到账减去全部开销后剩下的钱；买基金等投入也算，每月取用存款则填负数。没想好可以不填": "Money left after deducting all expenses from your monthly income; investments such as fund purchases also count, and withdrawals from savings should be entered as a negative number. Leave blank if unsure.",
  "每月到账（税后）": "Monthly Inflow (After Tax)",
