  "每月收入": "Monthly Income",
  "每月正投入参照减少 {v1}；分阶段正投入按比例调整，负投入和约定付款保留。": "The monthly positive contribution baseline is reduced by {v1}; phased positive contributions are adjusted proportionally, while negative contributions and scheduled payments are retained.",
