  "每月生活预算为行，目标月份为列": "Rows are monthly living budgets; columns are target months.",
  "每月盘一次最容易忘。开启后用系统通知提醒，只保存在这台电脑，不进入资料与备份。": "The monthly check-in is easy to forget. Turn on system notifications to remind you; reminders are stored only on this computer and are not included in data or backups.",
  "每月盘一次钱最容易忘。开启后用系统通知提醒你；提醒只保存在这台手机，不进入资料与备份。": "The monthly check-in is easy to forget. Turn on system notifications to remind you; reminders are stored only on this phone and are not included in data or backups.",
  "每月盘一次钱最容易忘。开启后用系统通知提醒你；提醒只保存在这台电脑，不进入资料与备份。": "The monthly check-in is easy to forget. Turn on system notifications to remind you; reminders are stored only on this computer and are not included in data or backups.",
  "每月约 {v1}": "About {v1} per month",
  "每月能存多少": "How Much You Can Save Each Month",
  "每月能存多少钱（元）": "How much you can save per month (CNY)",
  "每月能存的钱": "Money You Can Save Each Month",
  "每月能存的钱、收益等假设和已保存的规划基准都没有自动改变。": "Assumptions such as monthly savings and returns, and saved planning baselines, have not changed automatically.",
  "每月能存的钱是否已经扣除了这笔费用？尚未发生的计划请选择另外加上或本次不算。": "Has this expense already been deducted from the amount you can save each month? For planned expenses that have not happened yet, choose to add it separately or exclude it this time.",
