  "每月金额（元）": "Monthly Amount (CNY)",
  "每月需要存多少钱": "How Much You Need to Save Each Month",
  "每月需要存的钱可能偏低": "The monthly amount you need to save may be too low",
  "每月需要存的钱可能偏高": "The monthly amount you need to save may be too high",
  "每月需要存的钱可能变化，方向尚不确定": "The monthly amount you need to save may change; the direction is not yet clear.",
  "每月预算分项": "Monthly Budget Breakdown",
  "每月预计净到账金额": "Estimated Net Monthly Inflow",
  "每月预计净到账金额须为非负金额，最多两位小数。未知请留空。": "The expected monthly net income must be a non-negative amount with up to two decimal places. Leave blank if unknown.",
  "每期 {v1} / {v2}": "Per period: {v1} / {v2}",
  "每期 {v1} · {v2}": "{v1} per period · {v2}",
  "每期付款日与生效日不同": "Payment date and effective date differ for each period.",
  "每期价格": "Price per Period",
  "每期价格或单次金额（未年化原始金额；周期不同不代表负担可比）": "Price per period or one-time amount (original amount before annualization; different periods do not mean the burden is comparable)",
  "每期价格未知": "Price per period is unknown",
  "每期备款提醒需要关联订阅计划": "Per-period payment reminders require a linked subscription plan.",
  "每期实付": "Actual Payment per Period",
  "每期扣款前 {v1} 天提醒；下次 {date}。确认真实扣款后转到下一期。": "Remind {v1} day(s) before each payment; next on {date}. After confirming the actual charge, move to the next period.",
  "每期扣款前 {v1} 天提醒；下次 {v2}。确认真实扣款后转到下一期。": "Remind {v1} day(s) before each charge; next {v2}. Move to the next period after confirming the actual charge.",
  "每期提前 {v1} 天": "{v1} day(s) before each period",
  "每期提前提醒；确认已付后撤销该期，继续提醒下一期": "Remind before each period; after confirming payment, cancel that period and continue with the next.",
  "每期提醒": "Per-Period Reminder",
  "每期服务开始前多少天付钱；当天付就选「当天」": "How many days before each service period starts to pay; choose “Same day” to pay on that day.",
  "每期金额": "Amount per Period",
  "每条记录最多保存 20 张图片。": "Each record can store up to 20 images.",
  "每次": "Each Time",
  "每次付款的总额：按季付就填一整季的钱": "Total amount per payment: for quarterly payments, enter the full quarter.",
  "每次卖旧车回收": "Amount recovered each time an old car is sold",
  "每次只改一个条件，固定事件付款保留。FIRE 下期末资金可能因推迟停工而增加，请一起看准备就绪月份。": "Change only one condition at a time; fixed event payments are kept. Under FIRE, end-of-period funds may increase because you stop working later, so also check the readiness month.",
  "每次只改变所选条件，其余保持一致。输入值是本次假设；算出的“至少要攒多少”不会自动当成你的收入。": "Only the selected condition changes each time; everything else stays the same. The input values are assumptions for this run; the calculated “minimum amount to save” is not automatically treated as your income.",
  "每次完整盘点后第一次打开目标页时，记下当时的结论。按当时的条件计算，之后修改目标不会改写这里；带 * 的是当时仍有需确认事项。历史数字也保留当时的计算方法，跨版本差额不保证直接可比。": "The first time you open the Goals page after each full check-in, the conclusion at that time is recorded. It is calculated using the conditions at that time; later changes to the goal will not rewrite it. A * marks items that still had pending confirmations at the time. Historical figures also keep the calculation method used at the time, so differences across versions are not guaranteed to be directly comparable.",
  "每次打开物谱需要{name}验证。": "Thingary requires {name} verification every time it opens.",
  "每次打开物谱需要验证身份": "Thingary requires identity verification every time it opens.",
  "每次换车卖旧车回收": "Old car resale proceeds per replacement",
  "每次换车实际花的是价格减去这笔": "The actual cost of each car replacement is the price minus this amount.",
  "每次盘点记录一个日期上各账户的余额与欠款。完整表示应盘账户都有金额；快速更新可能沿用旧值，不代表全部重新核对。": "Each check-in records the balance and amount owed for every account on a given date. Full means every account due for check-in has an amount; a quick update may reuse old values and does not mean everything was rechecked.",
  "每笔贷款退休前后怎么还，可以随时回来修改。": "You can come back anytime to change how each loan is repaid before and after retirement.",
  "每类最多 500 项": "Up to 500 items per category",
  "每行从资金起点起汇总最多12个月，不是日历年；期末资产是该行结束时的余额。解锁、大额支出及里程碑可展开查看。": "Each row summarizes up to 12 months from the cash flow start, not a calendar year; ending assets is the balance at the end of that row. Unlocks, major expenses, and milestones can be expanded.",
  "每行只改变一项，其余沿用当前填写。默认的 1,000 元只是可修改的对照幅度，不代表收入预测或发生概率；不会改写上面的输入。": "Each row changes only one item; the rest use the current entries. The default ¥1,000 is just an adjustable comparison amount, not an income forecast or probability; it will not rewrite the inputs above.",
  "每行默认保持不变；在“全部设为”选择可一次填满整列。": "Each row stays unchanged by default; use “Set all to” to fill an entire column at once.",
  "每行默认保持不变；在“全部设为”选择可一次填满整列，再单独改个别行。": "Each row stays unchanged by default; use \"Set All\" to fill the entire column at once, then adjust individual rows.",
