  "比较一组相同收益的不同排列：年率 {v1} 的下跌分别放在退休开头和末段，持续时间相同、最多一年，其余时间沿用所设收益。基准不含下跌；两条压力路径的差异来自发生时点。": "Compare different orderings of the same returns: a decline at an annual rate of {v1} is placed at the start and end of retirement, with the same duration of up to one year, while the configured return applies the rest of the time. The baseline excludes the decline; the difference between the two stress paths comes from when it occurs.",
  "比较两次盘点": "Compare Two Check-ins",
  "比较任意两次盘点 →": "Compare Any Two Check-ins →",
  "比较储蓄、收益和预算": "Compare savings, returns, and budget",
  "比较储蓄、收益率、退休月份和支出。绿色表示比基础计划更好，黄色表示更差。红色表示存在缺口或没有剩余资金；黑框是基础计划。": "Compare savings, return rate, retirement month, and spending. Green means better than the baseline plan; yellow means worse. Red means there is a shortfall or no funds left; the black outline is the baseline plan.",
  "比较其他两次盘点 →": "Compare Two Other Check-ins →",
  "比较复工后按当前净投入的零、四分之一、一半和四分之三储蓄时，高收入需要持续到什么时候；具体结论见下方。": "Compare how long high income must last when saving zero, one quarter, half, or three quarters of the current net contribution after returning to work; see the conclusions below.",
