  "没有设置资金底线，只检查支付能力，不代表资金安全。": "No minimum balance is set; only your ability to pay is checked, not whether your funds are safe.",
  "没有账号，资料保存在本机，应用不上传资料。资料使用完全离线；只有你开启“启动时检查更新”或主动点“检查更新”时，才会向 Gitee 和 GitHub 的公开版本列表各查询一次，附普通网络信息与应用版本标识，不发送资料、设备或使用信息。下载和安装始终由你决定。": "No account. Your data stays on this device and the app never uploads it. Everything works fully offline. Only when you turn on “Check for updates on launch” or tap “Check for updates” yourself does it query the public release lists on Gitee and GitHub once each, sending standard network information and the app version identifier — never your data, device, or usage information. Downloads and installs are always your decision.",
  "没有账号，资料保存在这台手机，应用不上传资料，使用完全离线。": "No account. Your data stays on this phone, the app never uploads it, and everything works fully offline.",
