  "流动资金是计入净资产的现金与存款；投资是计入净资产的投资账户、混合投资、基金、债券和贵金属。公积金、个人养老金、保险、房产等不在这两条线里。面积独立显示，不相加；变化含存取与估值，不等于收益。": "Liquid funds are the cash and deposits counted in net worth; investments are the investment accounts, mixed investments, funds, bonds, and precious metals counted in net worth. Housing fund, personal pension, insurance, and property are not part of these two lines. Areas are shown independently and are not added together; changes include contributions and withdrawals plus valuation, so they are not returns.",
