  "灵活": "Flexible",
  "点「写邮件反馈」会同时复制物谱版本、iOS 版本和设备类型，粘贴到邮件里即可，不包含你的资料。收件地址：{feedbackEmail}": "Tap “Email Feedback” to also copy the Thingary version, iOS version, and device type; paste them into the email. Your data is not included. Send to: {feedbackEmail}",
  "点「添加图片」上传自己的图片。": "Tap “Add Image” to upload your own image.",
  "点一年可看全部字段。支出含大额付款，缺口单列。": "Tap a year to see all fields. Spending includes large payments; shortfalls are listed separately.",
  "点一项可排序、重命名、停用或删除。停用后不再出现在选择里，已有记录不受影响。": "Tap an item to reorder, rename, disable, or delete it. Disabled items no longer appear in selections; existing records are unaffected.",
  "点一项可排序、重命名或移除。移除时引用会迁移到你指定的目标，不会删除任何物品。": "Tap an item to reorder, rename, or remove it. When you remove one, references move to the target you choose; no items are deleted.",
  "点一项可改名、调整顺序或删除。": "Tap an item to rename, reorder, or delete it.",
  "点任一条会打开原记录。月支出含购入、维护、重要支出、周期付款与虚拟资产价格，退款冲减；盘点金额是净资产较上次的变化，不计入支出。": "Tap any entry to open the original record. Monthly spending includes purchases, maintenance, major expenses, recurring payments, and virtual asset prices, minus refunds; the check-in amount is the change in net worth since the last check-in and is not counted as spending.",
  "点击即可使用": "Tap to use",
  "点击年度柱或按 Enter 进入该年；悬浮或聚焦查看精确支出、退款、净支出、售出回收与金额待补笔数。所有年份都不保证记录完整。": "Tap a year bar or press Enter to open that year; hover or focus to see exact spending, refunds, net spending, sale proceeds, and the number of entries with amounts to be added. No year is guaranteed to have complete records.",
  "点击按{v1}排列": "Tap to sort by {v1}",
