  "用「记一笔资金流动」记录一次转账、投入或取回。": "Use “Record a Cash Flow” to log a transfer, contribution, or withdrawal.",
  "用一套完整样例体验物品、心愿、账户盘点和周期费用。可以放心编辑和删除，所有变化只留在样例中；样例不接受新增物品（实现心愿也会新增物品），点“新增物品”会回到自己的资料。": "Try out items, wishes, account check-ins, and recurring costs with a complete sample. Feel free to edit and delete; all changes stay in the sample. The sample doesn't accept new items (fulfilling a wish also adds an item), so tapping “Add Item” takes you back to your own data.",
  "用一套完整的虚构样例体验物品、心愿、账户盘点和周期费用。可以放心编辑和删除，样例不影响自己的资料。": "Try out items, wishes, account check-ins, and recurring costs with a complete fictional sample. Feel free to edit and delete; the sample doesn't affect your own data.",
