  "用于分类列表中的小标识，不影响物品封面。": "Used as a small marker in category lists; doesn't affect the item cover.",
  "用于安排本段每期的付款日期；实际扣款记录仍按真实日期填写。": "Sets each period's payment date in this section; actual charges are still recorded with their real dates.",
