  "股票归属、大额奖金、兼职等，仅填资金截至日之后明确假设会到账、且不在月储蓄中的税后金额。已在起点资产里的钱不要再填；未确定的股权和奖金不计入。": "For stock vesting, large bonuses, side income and similar, enter only after-tax amounts you explicitly assume will arrive after the funds-as-of date and that aren't part of monthly savings. Don't include money already in starting assets; unconfirmed equity and bonuses aren't counted.",
