  "自动发现新版本？": "Automatically detect new versions?",
  "自动备份": "Automatic Backup",
  "自动备份在资料有改动后自动生成，保留最近 7 份，放在本机资料目录旁；与手动备份格式相同，都可用于恢复。额外备份位置由你选择，可保存副本到云盘或外接盘。": "Automatic backups are created after your data changes, keep the latest 7 copies, and are stored next to your local data folder; they use the same format as manual backups and can also be used to restore. You choose the extra backup location, so you can save copies to cloud storage or an external drive.",
