  "账户、完整盘点与月度收入共用导入向导；模板与虚构样例在向导内。日常记收入请到收支记录。": "Accounts, full check-ins, and monthly income share one import wizard; templates and fictional samples are inside the wizard. To record day-to-day income, go to Income & Expenses.",
  "账户、完整盘点与月度收入可以一起保存，全部成功才写入。金额单位元；欠款填正数；不会修改收益等假设或已保存的规划基准。": "Accounts, check-ins, and monthly income can be saved together; nothing is written unless all succeed. Amounts are in yuan; enter debts as positive numbers; return assumptions and saved planning baselines are not modified.",
  "账户、盘点、收入或映射在预览后已变化，请重新预览整批": "Accounts, check-ins, income, or mappings changed after the preview. Please preview the whole batch again.",
  "账户不在所选日期的持仓范围内。": "The account is not in the holding range for the selected date.",
  "账户不在所选日期范围内。": "The account is not within the selected date range.",
  "账户与外部之间的非投资收益本金移动：外部投入为 外部→账户，取回本金为 账户→外部。": "Principal movements unrelated to investment returns between accounts and external sources: external contributions flow External → Account; principal withdrawals flow Account → External.",
