  "转账": "Transfer",
  "转账仅支持相同币种，请分别修改余额": "Transfers only support the same currency; adjust each balance separately.",
  "转账只更新两个账户的余额，不建立收入、支出或资金流动记录。仅支持金额已知、币种和计入范围相同的资产转出；持仓账户请用增减持仓。外币按原币金额转账，并共用本次汇率；若旧汇率不同或逐账户舍入使人民币变化无法相互抵消，请分别修改余额。只有这两个账户的人民币净变化为零才能保存，其他账户的计入范围变化仍按盘点比较提示。": "Transfers update only the two account balances and do not create income, expense, or cash flow records. Only asset transfers with a known amount and the same currency and inclusion scope are supported; for holding accounts, use increase or decrease holding. Foreign currency transfers use the original-currency amount and share this exchange rate; if the old rate differs or per-account rounding prevents the RMB changes from offsetting, adjust each balance separately. You can save only when the net RMB change in these two accounts is zero; inclusion-scope changes in other accounts are still flagged by check-in comparisons.",
