  "还没有付款记录": "No payment records yet.",
  "还没有付款记录。到期后点「确认已付」或「本期不付」就会记在这里。": "No payment records yet. When due, tap \"Confirm Paid\" or \"Skip This Period\" and it will be recorded here.",
