  "还没有关联的服务档案。保存后从详情面板点「建立关联服务档案」，只新增档案、不动已有付款。": "No linked service profile yet. After saving, tap \"Create Linked Service Profile\" in the details panel; this only adds a profile and leaves existing payments unchanged.",
  "还没有分组": "No groups yet.",
  "还没有分组，可创建“应急金”等分组；账户也可以保持未分组。": "No groups yet. You can create groups such as \"Emergency Fund\"; accounts can also remain ungrouped.",
