  "还没有售出记录。": "No sales records yet.",
  "还没有图片，可在“编辑资料”中添加。": "No image yet. You can add one in \"Edit Profile\".",
  "还没有备注。记下购买的缘由，或使用中的小细节。": "No notes yet. Jot down why you bought it, or any small details from using it.",
  "还没有大额计划": "No major plans yet.",
  "还没有大额计划。需要比较大额支出时，可以从上面的模板添加一个设想（买房、买车、装修、婚礼与彩礼、生育与养孩子、子女教育、旅行，或其他）；预设金额与年限仅作占位，请按自己的情况修改，只勾选本次要计入的安排。": "No major plans yet. When you need to compare major expenses, you can add a scenario from the templates above (buying a home, buying a car, renovation, wedding and bride price, having and raising a child, children's education, travel, or other); the preset amounts and terms are placeholders only, so adjust them to your situation and select only the arrangements to include this time.",
  "还没有完整盘点": "No full check-in yet.",
  "还没有完整盘点。": "No full check-in yet.",
