  "还没有完整盘点，净资产保持未知。": "There is no full check-in yet; net worth remains unknown.",
  "还没有完整盘点：先填现在能用来准备退休的钱和截至日期，不会创建盘点，也不会和账户余额相加。": "No full check-in yet: enter the money you can currently set aside for retirement and the as-of date. This won't create a check-in or add to account balances.",
  "还没有完整盘点；完成第一次完整盘点后开始计时。": "No full check-in yet; the clock starts after your first full check-in.",
