  "还没有已完成的导入记录。可以关闭后重新选择文件。": "No completed imports yet. You can close this and choose a file again.",
  "还没有已知金额。": "No known amount yet.",
  "还没有已记录付款；恢复时一起回来。": "No payments recorded yet; they'll return with the restore.",
  "还没有带日期的事件。": "No dated events yet.",
  "还没有带日期的记录": "No dated records yet.",
  "还没有带购入日期的物品。": "No items with a purchase date yet.",
  "还没有标签。可按用途分组，例如「工作用」；也可按位置分组，例如「书房」。每件物品只能选一个标签，具体位置建议写在备注里。": "No tags yet. You can group by use, such as \"Work\"; or by location, such as \"Study\". Each item can have only one tag; put the specific location in the notes.",
  "还没有添加收入。例如养老金、企业年金或租金。": "No income added yet. For example, a pension, employer annuity, or rent.",
