  "这个币种不支持小数，请填写整数。": "This currency doesn't support decimals. Enter a whole number.",
  "这个文件已于 {v1} 导入，其中 {count} 个对象已被删除或清除。可从最近删除恢复尚未清除的对象；或修改文件内容并重新核对外部编号／更换映射集合后重新导入。已清除对象的原外部编号不能在原映射集合重新绑定。同批指纹相同不会再次写入。": "This file was imported on {v1}; {count} of its objects have since been deleted or purged. You can restore objects that haven't been purged from Recently Deleted, or edit the file and recheck the external IDs or switch mapping sets before importing again. The original external IDs of purged objects can't be rebound in the original mapping set. Objects with the same fingerprint in the same batch won't be written again.",
  "这个文件已于 {v1} 导入，其中 {count} 条记录已被删除或永久清除。可从最近删除找回尚未永久清除的记录；也可修改文件内容，重新核对表格编号或换用另一套账户对应方案后导入。已永久清除的记录在原方案中用过的表格编号不能再关联新记录。系统识别为同一批内容时不会重复写入。": "This file was imported on {v1}; {count} record(s) have since been deleted or permanently purged. You can recover records that haven't been permanently purged from Recently Deleted, or edit the file and recheck the spreadsheet IDs or use a different account mapping scheme before importing again. Spreadsheet IDs used by permanently purged records in the original scheme can't be linked to new records. When the system identifies the same batch, it won't be written again.",
