  "这个计划用了固定天数、试用、暂停或分段价格等高级设置，手机上只能改名称、分类和备注；其余设置请在电脑上修改。": "This plan uses advanced settings such as a fixed number of days, trials, pauses, or tiered pricing. On mobile, you can only change the name, category, and notes; edit the other settings on a computer.",
  "这个订阅用了固定天数、试用、暂停或分段价格等高级设置，手机上只能改档案信息；付款设置请在电脑上修改。": "This subscription uses advanced settings such as a fixed number of days, trials, pauses, or tiered pricing. On mobile, you can only edit profile information; edit payment settings on a computer.",
  "这个账户不在所选日期的盘点范围内。": "This account isn't included in the check-in for the selected date.",
  "这个账户不在所选日期的盘点范围内。历史金额请到盘点记录更正。": "This account isn't included in the check-in for the selected date. Correct historical amounts in the check-in records.",
