  "这个账户还没有盘点记录。": "This account has no check-in records yet.",
  "这些事实没有已知日期，不放入任何月份；补填日期后会自动归位。": "These facts have no known date and aren't placed in any month; they'll move into place automatically once a date is backfilled.",
  "这些值用于试算与市场路径模拟，不保证未来收益；核对不等于保证。修改后关闭不会保存草稿。": "These values are used for what-if calculations and market-path simulations and don't guarantee future returns; confirming them isn't a guarantee. Closing after changes won't save a draft.",
  "这些压力测试均未实质性改变你的基础计划。": "None of these stress tests materially changed your base plan.",
