  "这些引用将迁移到你指定的目标；选「{nullLabel}」则改为未分类/未记录，不会删除任何物品。": "These references will be migrated to your chosen target; selecting \"{nullLabel}\" changes them to uncategorized/unrecorded and won't delete any items.",
