  "这只是防止旁人看到屏幕，不会加密资料库文件。可另行创建加密备份；本机资料库文件仍未加密。": "This only prevents others from seeing your screen; it doesn't encrypt the library file. You can create an encrypted backup separately; the local library file remains unencrypted.",
