  "这是「删政策测算、留客观事实」后的第四问与时间输入原型：养老金是一种可选未来收入，官方只留链接。": "This is the fourth question and time-input prototype after \"remove policy projections, keep objective facts\": a pension is optional future income, with only an official link.",
  "这是一套虚构样例，功能已全部开启，随便点。资料只存这台电脑，不上传、未加密，自动备份在本机；想记录自己的，点按钮即可，样例不会带过去。": "This is a fictional sample with all features enabled, so feel free to explore. Data is stored only on this computer, isn't uploaded, and isn't encrypted; automatic backups are created locally. To record your own data, click the button; the sample won't carry over.",
  "这是两人合计每月要存的钱：伴侣还在工作时，包含伴侣那一份。": "This is the total amount you both need to save each month: it includes your partner's share while they're still working.",
  "这是估计金额": "This is an estimated amount.",
  "这是你自己的估计；没想好可以留空。": "This is your own estimate; leave it blank if you're unsure.",
  "这是假设；商贷与公积金贷款利率不同，公积金贷款暂未单独建模": "This is an assumption; commercial and provident fund loan rates differ, and provident fund loans aren't modeled separately yet.",
  "这是手填的未来收入假设；领取资格和金额请另行核实。": "This is a manually entered assumption for future income; verify eligibility and amounts separately.",
  "这是把两段实际收益各调低或调高 2 个百分点后重新计算的对照，不代表发生的概率。": "This compares results recalculated after adjusting each of the two actual return periods up or down by 2 percentage points; it doesn't represent the probability of occurrence.",
  "这是旧版关联的订阅，没有服务开始日期；手机上只能改档案信息，请在电脑上补充开始日期。": "This is a subscription linked from an older version and has no service start date. On mobile, you can only edit profile information; add the start date on a computer.",
  "这是未选择时的显示名称，请换一个名称。": "This is the display name used when nothing is selected. Please choose another name.",
  "这是软件算出的参考金额，不用你填写，也不会自动保存成你每月能存的钱。这里的存钱是收入减去开销后留下的钱，买基金等投入也算，投资涨跌另算。": "This is a reference amount calculated by the app. You don't need to fill it in, and it won't automatically be saved as the amount you can save each month. Savings here means the money left after income minus expenses, including contributions such as fund purchases; investment gains and losses are counted separately.",
  "这是通用假设，不代表实际待遇调整": "This is a general assumption and doesn't represent an actual benefit adjustment.",
  "这期付款记录尚未读取，合计暂不可用。": "This period's payment records haven't been loaded, so the total isn't available yet.",
  "这期尚无已记录收入，不代表实际收入为零。": "No income has been recorded for this period; this doesn't mean actual income is zero.",
  "这期已记录税后收入 {v1}；不代表收入已记全。": "After-tax income of {v1} has been recorded for this period; this doesn't mean all income is recorded.",
  "这期暂无可比较的资产变化。": "There are no comparable asset changes for this period yet.",
  "这期暂无已记录的购入、支出或周期付款，不代表实际没有支出。": "No purchases, expenses, or recurring payments have been recorded for this period; this doesn't mean there were no actual expenses.",
  "这期有 {length} 条已记录的购入、支出或周期付款，合计约 {v2}（退款与售出回收已扣除）{v3}；这些记录只用于解释，不调整资产数字。": "This period has {length} recorded entry(ies) for purchases, expenses, or recurring payments totaling about {v2} (net of refunds and sale proceeds) {v3}; these records are only for explanation and don't adjust asset figures.",
  "这期有账户改变了计入设置，变化不能与上期直接比较。": "Some accounts changed their inclusion settings this period, so changes can't be compared directly with the previous period.",
  "这期还没有收入记录；有收入时可补录。": "No income has been recorded for this period yet; you can backfill it once there is income.",
  "这条{label}会从「{assetName}」的详情和统计中隐藏，费用与保障摘要会立即重算。之后可以从“最近删除”恢复；删除不代表退役或售出。": "This {label} will be hidden from the details and stats for \"{assetName}\", and the cost and coverage summaries will be recalculated immediately. You can restore it from Recently Deleted later; deleting doesn't mean it has been retired or sold.",
  "这条发生记录已有实际事实，请在原来源核对更正。": "This occurrence record already contains actual data. Check and correct it at the original source.",
  "这条心愿不在可记录购入的状态": "This wish isn't in a state where a purchase can be recorded.",
  "这条心愿在最近删除中，请先恢复": "This wish is in Recently Deleted. Restore it first.",
