  "这条心愿当前不能记录购入，可能已经处理过，请返回重新读取。": "This wish can't record a purchase right now; it may have already been handled. Go back and reload.",
  "这条心愿没有原关联物品；请使用记录购入或关联已有物品": "This wish has no originally linked item; use Record Purchase or Link Existing Item.",
