  "这条来源所属功能已关闭，请启用后重新打开。": "The feature this source belongs to is turned off. Enable it and reopen this source.",
  "这条来源记录已删除或失效，请返回后重新读取。": "This source record has been deleted or is no longer valid. Go back and reload it.",
  "这条盘点已删除或变化，请返回后重新读取。": "This check-in has been deleted or changed. Go back and reload.",
