  "这条记录已有实际事实，不可撤回；请核对更正付款或贷款资料。": "This record already contains actual data and can't be undone; check and correct the payment or loan details.",
  "这条记录没有原关联物品；确认购入请直接记录这次购入或关联已有物品。": "This record has no originally linked item. To confirm the purchase, record the purchase directly or link an existing item.",
  "这条记录没有实际付款、来源或贷款事实。撤回只去掉发生记录，保留计划资料。": "This record has no actual payment, source, or loan data. Undoing it removes only the occurrence record and keeps the planning details.",
