  "这次盘点没有需要安排的负债账户。": "This check-in has no liability accounts that need scheduling.",
  "这次要不要算养老金等退休收入？也可以选择先不算。": "Do you want to include pension and other retirement income this time? You can also choose to skip it for now.",
