  "这笔付款对应服务：{v1}。实付日期填写真正扣款的那一天，可以早于服务生效日；不会改变后续排期。": "This payment is for {v1}. For the actual payment date, enter the day the charge occurred; it can be earlier than the service start date and won't affect future scheduling.",
  "这笔充值": "This Top-Up",
  "这笔充值已不存在。": "This top-up no longer exists.",
  "这笔支出在目标月份 {target} 前就结束了，不会影响结果：退休前的花费请算进每月能存多少里。": "This expense ends before the target month {target}, so it won't affect the result. For pre-retirement spending, include it when calculating how much you can save each month.",
  "这笔支出已不存在，可能已被删除。": "This expense no longer exists and may have been deleted.",
  "这笔收入是什么": "What is this income?",
