  "这笔还款已经含在我的每月开销里": "This repayment is already included in my monthly expenses.",
  "这笔金额会让心愿达到目标并自动实现，但样例里不能新增物品，所以没有保存。想体验实现心愿，请先点顶部「开始记录我的资料」。": "This amount would bring the wish to its goal and fulfill it automatically, but items can't be added in the sample, so it wasn't saved. To try fulfilling a wish, first tap \"Start Recording My Data\" at the top.",
  "这笔钱是否已含在生活费里，待确认": "Pending confirmation: whether this amount is included in living expenses",
  "这组订阅已有删除组，请重新读取最近删除": "A deletion group already exists for this subscription. Reload Recently Deleted.",
  "这组记录属于一个关联订阅删除组，请在最近删除中整组恢复": "These records belong to a linked subscription deletion group. Restore the whole group in Recently Deleted.",
  "这组记录已恢复或已清除，请重新读取最近删除": "These records were restored or permanently deleted. Reload Recently Deleted.",
