  "这部分还款未计入，结果可能偏乐观。": "This portion of the repayment was not included, so the result may be too optimistic.",
  "这里只保留上次操作的编号，没有保存原始 Excel。请先核对那次是否导入成功，不要重新选择文件重复导入。": "Only the ID from the last operation is kept here; the original Excel file was not saved. First check whether that import succeeded, and don't select the file again to repeat the import.",
  "这里同时检查空窗资金与退休目标。单看存款能花多久，可能得到另一个月数；本结果没有承诺你会在这段时间内找到工作。": "This checks both gap funds and the retirement goal at once. Looking only at how long your savings will last may give a different number of months; this result doesn't promise you'll find work during that time.",
