  "退休前实际收益率须在 -10.00% 到 20.00% 之间": "Pre-retirement actual rate of return must be between -10.00% and 20.00%.",
  "退休前实际收益请填百分数，例如 2 或 2.5。": "Enter the pre-retirement actual return rate as a percentage, e.g. 2 or 2.5.",
  "退休前指已从每月能存的钱里扣除；退休后指已含在生活费里。另一适用段未填写时，该段还款尚未确认。": "Before retirement means it has already been deducted from the amount you can save each month; after retirement means it is already included in living expenses. If the other applicable section isn't filled in, that section's repayment isn't confirmed yet.",
