  "闲置时长只在离开物谱后返回时检查；未完成的编辑、保存或待核对请求会延后验证，处理完后再锁定。": "The idle timeout is checked only when you return to Thingary after leaving it; unfinished edits, saves, or pending confirmation requests delay re-verification, and the app locks after they are handled.",
  "闲置时长只在离开窗口后返回时检查；未完成的编辑、保存或待核对请求会延后验证，处理完后再锁定。如需离开就遮住内容，请同时开启上方的遮挡选项。": "The idle timeout is checked only when you return after leaving the window; unfinished edits, saves, or pending confirmation requests delay re-verification, and the app locks after they are handled. To hide content when you leave, also turn on the cover option above.",
