  "需确认事项 {v1}": "Items needing confirmation {v1}",
  "需要两次完整盘点中的同一投资范围才能核对区间损益；没有投资账户时也不用填写资金流动。": "To reconcile period gains and losses, you need the same investment scope in two full check-ins; if you have no investment accounts, you don't need to enter cash flow either.",
  "需要先通过{name}验证才能开启；也可能无法保存设置，请重试。": "Verify with {name} first to enable this; settings may also fail to save, so try again.",
  "需要免费试用、固定天数、暂停续费等高级设置？改用完整表单": "Need advanced settings like a free trial, fixed days, or pausing renewals? Use the full form.",
