  "领域拒绝了本次输入，请核对以下字段后重试：": "The domain rejected this input. Check the following fields and try again:",
  "额外备份位置": "Additional Backup Location",
  "额外备份位置不可用：外接盘未连接": "Additional backup location unavailable: external drive not connected",
  "额外备份位置未取消，请重试": "The additional backup location was not removed. Please try again.",
  "额外备份位置未取消：": "Additional backup location was not cancelled:",
  "额外备份位置未更新，请重试": "The additional backup location was not updated. Please try again.",
  "额外备份位置未更新：": "Additional backup location was not updated:",
  "额外备份位置选择请在原生 App 中验证，此页面仅展示界面状态。": "Additional backup location selection must be verified in the native app; this page only displays UI status.",
  "额外备份复制仍在进行，请稍后再试": "Additional backup copy is still in progress. Please try again later.",
  "额外缺口": "Additional Shortfall",
  "额外计入": "Extra Included",
  "额度到期 {expires}": "Quota expires {expires}",
  "额度到期日": "Limit Expiry Date",
  "风险结果按完整预算、覆盖到规划终点；{v1}。": "Risk results are based on the full budget and extend to the end of the planning horizon; {v1}.",
  "首付": "Down Payment",
  "首付 / 一次付清的现金": "Down Payment / Lump-Sum Cash",
  "首付 {v1}": "Down Payment {v1}",
  "首付、杂费在计划月份一次性扣；借款金额按购买时预计的实际价格算，采用等额本息（每月还款总额相同），到期停止；物价变化只影响折算成今天的钱，不改变每月实际还款金额；月供与持有成本在退休前压低每月储蓄，退休后算进支出；省租先核对是否已经算入生活费或每月能存的钱，省下的房租不会自动加到每月能存的钱里；买车可设换车周期、截止年龄和每次卖旧车回收，每次实际花的是「价格减回收」；其他类的模板（装修、婚礼、养孩子、教育、旅行）都是同一套：一次性支出、可选分期，加上可选的每月持续支出和每隔几年重复，可设持续到哪个月；教育和旅行重复时每次花的是总价，没有回收。「首付付得起吗」按当前储蓄推演到计划月份的可支配资产，对照首付、杂费与应急金线。价格按今天的钱，默认实际不涨价，想保守就填高一点。公积金贷款与提取暂未单独建模。": "The down payment and closing costs are deducted at once in the planned month. The loan amount is based on the estimated actual purchase price, uses equal principal and interest (the same total monthly payment), and stops at maturity. Price changes only affect the conversion to today's money and do not change the actual monthly payment. Before retirement, the monthly payment and holding costs reduce monthly savings; after retirement, they count as expenses. For rent savings, first check whether they are already included in living expenses or the amount you can save each month; the rent saved is not automatically added to the amount you can save each month. For car purchases, you can set a replacement cycle, an end age, and the resale amount each time you sell the old car; each time, the actual cost is \"price minus resale\". Templates for other categories (renovation, wedding, raising a child, education, travel) work the same way: a one-time expense, optional installments, plus optional recurring monthly expenses that repeat every few years and can be set to continue until a chosen month. When education and travel repeat, each occurrence costs the full price, with no resale. \"Can I afford the down payment?\" projects disposable assets from current savings to the planned month and compares them with the down payment, closing costs, and emergency fund threshold. Prices are in today's money and are assumed not to rise in real terms by default; enter higher amounts if you want to be conservative. Housing provident fund loans and withdrawals are not yet modeled separately.",
  "首付不能高于总价。": "Down payment cannot exceed the total price.",
  "首付付得起吗": "Can I afford the down payment?",
  "首付和杂费等都已列出；部分付款保持关闭。": "Down payment and closing costs are listed; partial payments remain off.",
  "首付或一次付清": "Down Payment or Pay in Full",
  "首付等一次性支出和月供等持续费用都算进退休测算。请核对这些费用是否已经含在生活费里，没含的另算一次。这里只估算，不扣实际资金。": "One-time expenses such as the down payment and ongoing costs such as monthly payments are included in the retirement projection. Check whether these costs are already included in living expenses; if not, add them separately. This is an estimate only and does not deduct actual funds.",
  "首份加密备份：失败（{v1}）— {message}": "First encrypted backup: failed ({v1}) — {message}",
  "首份加密备份：成功（{v1}）": "First encrypted backup: successful ({v1})",
  "首份加密备份：无记录": "First encrypted backup: no record",
  "首份加密备份：等待": "First encrypted backup: waiting",
  "首份加密备份：进行中": "First encrypted backup: in progress",
  "首期 {v1}": "First period {v1}",
  "首期付款日另算": "The first payment date is calculated separately",
  "首期服务：{v1} 至 {v2}": "First-period service: {v1} to {v2}",
  "首期计划付款日": "First planned payment date",
  "首期计划付款：{firstDue} · {v2}／{v3}": "First planned payment: {firstDue} · {v2}/{v3}",
  "首次使用本版本，请选择加密或继续明文；选择前不会生成新的自动备份。已有备份不受影响。": "First time using this version: choose encryption or continue with plaintext. No new automatic backups will be created until you choose. Existing backups are unaffected.",
  "首次使用本版本：自动与额外备份已暂停，请选择加密或继续明文。": "First time using this version: automatic and additional backups are paused. Choose encryption or continue with plaintext.",
  "首次充值": "First top-up",
  "首次打开": "First opened",
  "马来西亚林吉特": "Malaysian ringgit",
  "验收提醒秒数必须在 10 至 600 之间": "Acceptance reminder seconds must be between 10 and 600",
