  "验证资料已由另一个进程打开": "Validation data is already open in another process",
  "验证身份后查看本机资料": "Verify your identity to view local data",
  "验证通过后会立即生成首份加密备份。验证成功不等于备份成功，两者分别显示。": "After verification succeeds, the first encrypted backup is created immediately. Verification success is not the same as backup success; they are shown separately.",
  "验证通过后会立即生成首份加密备份，即使资料没有变化。验证成功不等于备份成功，两者分别显示。": "After verification succeeds, the first encrypted backup is created immediately, even if the data has not changed. Verification success is not the same as backup success; they are shown separately.",
