  "默认从购买日期起一年；日期未知时从今天起，可修改结束日期": "Defaults to one year from the purchase date; if the date is unknown, starts today. The end date is editable.",
  "默认从购买日期起一年；购买日期未知时从今天起。": "Defaults to one year from the purchase date; starts today if the purchase date is unknown.",
  "默认关闭；开启后按系统通知权限执行，关闭、停用或结束会撤销待通知。": "Off by default; when enabled, it follows system notification permissions; turning it off, disabling it, or ending it cancels pending notifications.",
  "默认关闭；打开后默认 7 天，从开始日计入第一天": "Off by default; when on, defaults to 7 days, counting the start date as day one",
  "默认同时适用于退休前与退休后，不另外扣款，也不自动增加到期后的生活费。": "By default, it applies both before and after retirement, with no separate deduction and no automatic increase in living expenses after it ends.",
  "默认图标": "Default icon",
  "默认实付＋赠送，随两项联动；手动修改后停止": "Defaults to amount paid + bonus, linked to both fields; stops after manual edit.",
  "默认币种": "Default Currency",
  "默认按领取时的金额，与官方测算数字更容易对应": "Defaults to the amount at claim, making it easier to match official projections",
  "默认无赠送；不计入投入": "No bonus by default; not counted as invested",
  "默认沿用上次单价，可修改。": "Defaults to the last unit price; editable.",
  "默认物品图标": "Default item icon",
  "默认箱子图标": "Default box icon",
